python3 - <<'P'
import re,time
t=str(int(time.time()))
def swap(page,mainf):
    s=open(page,encoding='utf-8').read(); m=open(mainf,encoding='utf-8').read()
    s=re.sub(r'<main.*?</main>',lambda x:m,s,count=1,flags=re.S)
    open(page,'w',encoding='utf-8').write(s)
swap('pdf.html','editor-s1.main.html'); swap('assistant.html','assistant-s1.main.html')
for p in ['pdf.html','assistant.html','money.html','voice.html','chat.html','atlas.html']:
    s=open(p,encoding='utf-8').read()
    s=re.sub(r'<link rel="stylesheet" href="/web/nox-ds-s1\.css[^"]*">','',s)
    s=s.replace('</head>','<link rel="stylesheet" href="/web/nox-ds-s1.css?v=%s"></head>'%t,1)
    for f in ['nox-fin-s1.js','nox-voice-s1.js','nox-atlas-s1.js','nox-chat-tg.js','nox-editor-s1.js','nox-assistant-s1.js']:
        s=re.sub(f.replace('.','\\.')+r'\?v=[0-9]*',f+'?v='+t,s)
    open(p,'w',encoding='utf-8').write(s)
print('ds ok')
P
